-- =====================================================
-- POI MEDIA — WIKIMEDIA COMMONS IMAGES + CREDIT — MIGRATION 0100
-- =====================================================
-- 0061 gave 37 of the original 70 POIs a Wikipedia lead image. The 2026-10 POI
-- batch (scripts/poi-seed) added ~110 POIs in 10 zones without any photo, so
-- every zone but Málaga looked empty. This fills 128 of the 149 POIs
-- that had no media, one PRIMARY_IMAGE each, uploaded to R2 under guide/pois/.
--
-- Source: Wikimedia Commons, free licences only (CC0, CC BY, CC BY-SA). Found via
-- the POI's Wikipedia article (es/en) or its Wikidata P18, matched on name AND
-- distance to the POI's coordinates, or by a Commons search reviewed by hand.
-- Every image was checked by eye: maps, logos, signs, statues, wrong places and
-- duplicates were dropped. 21 POIs have no usable free photo (theme parks,
-- small museums, viewpoints) and stay without media until uploaded in the admin.
--
-- CC BY / CC BY-SA require crediting author + licence, which 0061 never stored.
-- The new columns keep it per image so the guide can show it; 0061's 27 rows
-- still have them NULL.
-- =====================================================

ALTER TABLE guide_poi_media ADD COLUMN source_url TEXT;
ALTER TABLE guide_poi_media ADD COLUMN author TEXT;
ALTER TABLE guide_poi_media ADD COLUMN license TEXT;
ALTER TABLE guide_poi_media ADD COLUMN license_url TEXT;

INSERT INTO guide_poi_media (id, poi_id, r2_key, media_type, role, width, height, file_size, order_index, source_url, author, license, license_url)
