WHERE EXISTS (SELECT 1 FROM guide_pois WHERE id = 'poi_mt0qfcfn_r5wfmx') AND NOT EXISTS (SELECT 1 FROM guide_poi_media WHERE poi_id = 'poi_mt0qfcfn_r5wfmx');
